// Assuming boxes_xyxy is a vector of arrays with 4 or 6 elements
using Box = std::array<double, 4>; // For (x1, y1, x2, y2)
using Boxes = std::vector<Box>;

// Assuming _area_range is a std::pair<double, double>
using AreaRange = std::pair<double, double>;

// Function to select boxes by area
std::vector<size_t> select_boxes_by_area(const Boxes& boxes_xyxy, const AreaRange& area_range) {
    if (area_range.first >= area_range.second) {
        throw std::invalid_argument("Area range must be [min, max], where min < max.");
    }

    std::vector<size_t> selected_indices;

    for (size_t i = 0; i < boxes_xyxy.size(); ++i) {
        const auto& box = boxes_xyxy[i];
        double width = box[2] - box[0];
        double height = box[3] - box[1];
        double area = width * height;

        if (area >= area_range.first && area <= area_range.second) {
            selected_indices.push_back(i);
        }
    }

    return selected_indices;
}

